// Shastriya words for checking search spellings, vyutpatti lookups and the
// folded search, each with the ways people actually type it in Roman letters
// (loosely, as a Gujarati or Hindi speaker would: no diacritics, final a
// dropped or kept, sh for both श and ष, gy/gn/jn for ज्ञ, ri for ऋ, n or m for
// the anusvāra). The list leans on the letters that are easy to get wrong:
// ऋ, ज्ञ, क्ष, त्र, श्र, श/ष/स, ण/न, ङ ञ and the anusvāra, visarga, avagraha,
// त्त्व, द्ध, द्व, ह्म, ष्ट, ष्ठ, र्य, ऐ, औ and long/short vowels.
//
// Spellings are Sanskrit (Devanagari is always Sanskrit here, never Hindi).

export type ShastriyaWord = {
  word: string;
  roman: string[];
};

