/** The Gujarati spelling of a Devanagari word, letter for letter. */
export function toGujarati(word: string) {
  return [...word]
    .map((ch) => {
      const code = ch.codePointAt(0)!;
      if (ch === "ऽ") return "ઽ";
      return code >= 0x0900 && code <= 0x097f ? String.fromCodePoint(code + 0x180) : ch;
    })
    .join("");
}
